        paths.setdefault(color, set()).update(cells)
        for r, c in cells:
            if 0 <= r < h and 0 <= c < w and out[r][c] == 0:
                out[r][c] = 5

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
