                out[r][c] = 3
                out[r+3][c] = 3
            elif color == 6:
                cells = [(x, c) for x in range(r-6, r+1)]
                draw(6, cells)
                out[r][c] = 6
                out[r-6][c] = 6

    # Crossings of the horizontal 2-tracks with vertical 3/6-tracks
